/* 訓練營：放入角色後經過指定時間領取經驗；訓練中的角色不能出戰。
   經驗設計參考：中期小兵一場約 300 經驗、1～2 分鐘，主動遊玩約每分鐘 200 經驗；
   訓練營是離線／掛機收益，每分鐘效率刻意低於主動遊玩，短方案效率較高，24 小時方案適合睡前放入。 */
const TRAIN_SLOTS = 3;
const TRAIN_PLANS = [
 {id:'m10', label:'10 分鐘', min:10, exp:400},
 {id:'m30', label:'30 分鐘', min:30, exp:1100},
 {id:'h1', label:'60 分鐘', min:60, exp:2000},
 {id:'d1', label:'24 小時', min:1440, exp:14400}
];
const MAX_LV = 100;
const TIERS = [
 {min:1, name:'見習海賊', color:'#9fb3c4'}, {min:20, name:'超新星', color:'#6fd08c'}, {min:40, name:'七武海級', color:'#5fb8ff'},
 {min:60, name:'大將級', color:'#c58bff'}, {min:80, name:'四皇級', color:'#ff9a4a'}, {min:100, name:'海賊王級', color:'#ffcf5a'}
];
const SKILL_UNLOCK = [1, 10, 30, 40, 60];
/* 篇章依原作時間線：東海 → 阿拉巴斯坦 → 空島 → 司法島 → 魚人島 → 和之國 → 蜂巢島（最終章開頭）→ 艾爾巴夫 */
const ENEMY_LEVEL = {east:8, alabasta:18, skypiea:28, enies:38, marineford:43, fishman:48, wholecake:54, wano:58, dark:70, giant:84};
const BOSS_LEVEL_BONUS = 8;
const GACHA_CHAR_RATE = 0.03, GACHA_CHAR_LV = 20;
function expNeed(lv) { return Math.round(20 + lv * 6 + lv * lv * 0.1); }
/* 技能次數：LV1 起為原設 -3，LV30 +1，LV60 +2，LV100 恢復原設上限（至少 1 次） */
function ppDeltaAt(lv) { return lv >= MAX_LV ? 0 : lv >= 60 ? -1 : lv >= 30 ? -2 : -3; }
function tierOf(lv) { let t = 0; TIERS.forEach((x, i) => { if (lv >= x.min) t = i; }); return t; }
/* 單招次數：有 ppDelta [LV1, LV30, LV60] 的招式使用自己的成長方式，其餘套用共用規則 */
function skillPP(s, lv, adj) { if (!s.maxPP) return 0; const d = s.ppDelta ? (lv >= MAX_LV ? 0 : lv >= 60 ? s.ppDelta[2] : lv >= 30 ? s.ppDelta[1] : s.ppDelta[0]) : adj; return Math.max(1, s.maxPP + d); }
function lvStats(c, lv) {
  const k = lv / MAX_LV, t = tierOf(lv);
  const dmg = +(0.45 + 0.55 * k).toFixed(3);
  /* 攻擊力＝傷害倍率×1000；防禦力依體力與等級計算（每 100 點約減傷 1.6%，最多 25%） */
  return { hp: Math.round(c.maxHp * (0.40 + 0.60 * Math.pow(k, 0.9))), spd: Math.round(c.baseSpeed * (0.8 + 0.2 * k)), dmg, atk: Math.round(dmg * 1000), def: Math.round(c.maxHp * 0.3 * (0.45 + 0.55 * k)), ppAdj: lv >= 100 ? 0 : lv >= 60 ? -1 : lv >= 30 ? -2 : -3 };
}

