function charArt(id, kind) { const eq = (((typeof SAVE !== 'undefined' && SAVE.data && SAVE.data.skins) || {}).equip || {})[id], S = eq && SKINS[eq] && !SKINS[eq].soon ? SKINS[eq] : null; return S ? (kind === 'avatar' ? S.avatar : S.image) : CHARACTERS[id][kind === 'avatar' ? 'avatar' : 'image']; }
/* 組合獎勵：同時擁有 needs 裡的角色就免費加入（例如鷹眼＋莫莉亞 → 佩羅娜） */
function grantCombos() { if (typeof SAVE === 'undefined' || !SAVE.data || !SAVE.data.roster) return; Object.entries(CHAR_OBTAIN).forEach(([cid, o]) => { if (o.needs && !SAVE.data.roster[cid] && o.needs.every(x => SAVE.data.roster[x]) && typeof addCrew === 'function' && addCrew(cid, 20)) setTimeout(() => toast(`${o.needs.map(x => CHARACTERS[x].name).join('、')} 都在船上了——「${CHARACTERS[cid].title}」${CHARACTERS[cid].name}加入了船隊！`, 'gold'), 900); }); }
function grantSkins() { if (typeof SAVE === 'undefined' || !SAVE.data) return []; const S = SAVE.data.skins = SAVE.data.skins || { owned: [], equip: {} }; S.owned = S.owned || []; const got = [];
  Object.entries(SKINS).forEach(([k, s]) => { if (s.grantWith && !S.owned.includes(k) && SAVE.data.roster && SAVE.data.roster[s.grantWith]) { S.owned.push(k); got.push(k); } }); if (got.length) SAVE.save(); return got; }
